H.background();
const w = H.W, h = H.H;
const a = Math.round(P.a), b = Math.round(P.b), c = Math.round(P.c), d = Math.round(P.d);
// Common denominator method for a/b + c/d, shown as scaled bar models.
const bd = (b === 0 ? 1 : b), dd = (d === 0 ? 1 : d);
const lcd = Math.abs(bd * dd) || 1;
const num = a * dd + c * bd;
H.text("Add fractions: a/b + c/d", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Rescale BOTH to the common denominator b*d, then add the tops.", 24, 52, { color: H.colors.sub, size: 13 });
// Step reveal driven by t: 0 = show pieces, 1 = rescale, 2 = sum.
const step = Math.floor((t % 9) / 3);
const barX = 90, barW = w - 180, rowH = 46;
// One whole = the bar OUTLINE = `den` equal pieces. Lit pieces = `val`
// (may exceed `den` for an improper fraction, so the fill runs past one whole).
// A single shared piece-width keeps "a piece" the same physical size in every
// row and keeps the widest fill inside barW.
const maxVal = Math.max(a, c, a * dd, c * bd, Math.abs(num), lcd, 1);
const unit = barW / maxVal;             // px per single piece (1/den of a whole)
function bar(y, label, val, den, col, lit) {
  H.text(label, 24, y + rowH * 0.62, { color: H.colors.sub, size: 14 });
  const n = Math.max(1, Math.abs(Math.round(den)));
  const lo = Math.max(0, Math.round(val));
  const hh = rowH * 0.7;
  // outline marks the "one whole" = n pieces
  H.rect(barX, y, n * unit, hh, { stroke: H.colors.grid, width: 1.5, radius: 6 });
  for (let i = 0; i < lo; i++) {
    H.rect(barX + i * unit + 2, y + 2, unit - 4, hh - 4, { fill: col, radius: 3 });
  }
  // empty pieces inside the whole (when proper fraction)
  for (let i = lo; i < n; i++) {
    H.rect(barX + i * unit + 2, y + 2, unit - 4, hh - 4, { fill: H.colors.panel, radius: 3 });
  }
  if (lit) {
    const sx = barX + ((t * 0.6) % 1) * barW;
    H.line(sx, y - 4, sx, y + hh + 4, { color: H.colors.warn, width: 2 });
  }
}
let y0 = 92;
bar(y0, (a) + "/" + bd, a, bd, H.colors.accent, true);
bar(y0 + rowH + 14, (c) + "/" + dd, c, dd, H.colors.accent2, true);
